<div class="form-grid"><label>ชื่อ Challenge<input name="title" value="{{$challenge?->title}}" required></label><label>ไอคอน<input name="icon" value="{{$challenge?->icon??'🎯'}}" required></label><label>ประเภทกิจกรรม<select name="activity_type_id"><option value="">ทุกกิจกรรม</option>@foreach($activityTypes as $type)<option value="{{$type->id}}" {{$challenge?->activity_type_id===$type->id?'selected':''}}>{{$type->icon}} {{$type->name}}</option>@endforeach</select></label><label>เป้าหมาย<input type="number" name="target" min="1" value="{{$challenge?->target??1}}" required></label><label>คะแนนรางวัล<input type="number" name="reward_points" min="0" value="{{$challenge?->reward_points??10}}" required></label><label>วันเริ่ม<input type="date" name="starts_at" value="{{$challenge?->starts_at?->format('Y-m-d')??now()->format('Y-m-d')}}" required></label><label>วันสิ้นสุด<input type="date" name="ends_at" value="{{$challenge?->ends_at?->format('Y-m-d')??now()->addWeek()->format('Y-m-d')}}" required></label></div><label>รายละเอียด<textarea name="description" required>{{$challenge?->description}}</textarea></label><label class="check"><input type="checkbox" name="active" value="1" {{$challenge?->active===false?'':'checked'}}> เปิดใช้งาน</label>
